package cn.zhuatech.devagent.controller;
import cn.zhuatech.devagent.agent.AgentRuntime; import cn.zhuatech.devagent.common.ApiResponse; import cn.zhuatech.devagent.dto.DevAgentDto.*; import cn.zhuatech.devagent.service.DevAgentService; import cn.zhuatech.devagent.service.ChangeRiskService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final DevAgentService service;private final AgentRuntime runtime;private final ChangeRiskService changeRisk;public WorkspaceController(DevAgentService service,AgentRuntime runtime,ChangeRiskService changeRisk){this.service=service;this.runtime=runtime;this.changeRisk=changeRisk;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}@PostMapping("/agent-preview") public ApiResponse<AgentRuntime.AgentResult> preview(@RequestBody Map<String,String> body){return ApiResponse.ok(runtime.run(new AgentRuntime.AgentRequest(body.getOrDefault("objective","修复接口缺陷"),Map.of("mode","demo"))));}@PostMapping("/change-risk") public ApiResponse<ChangeRiskService.RiskResult> evaluate(@Valid @RequestBody ChangeRiskService.RiskRequest request){return ApiResponse.ok("变更风险评估完成",changeRisk.evaluate(request));}}
